4|import type { SessionModelSelection } from "@pi-gui/session-driver";
5|import type { OrchestrationChildRuntime } from "../../contracts/desktop-state";
6|
7|/**
8| * Which driver runs a sidekick/scout child's session. `pi` is the built-in
9| * pi-sdk-driver; `muse-cli` shells out to the official Muse Code CLI, which
10| * is the supported route for Meta-subscription (`meta/*`, OAuth) sidekicks:
11| * subscription requests must carry Muse Code's own tool declarations, so
12| * pi-sdk-driver children on those models fail with 403.
13| */
14|
15|export type { OrchestrationChildRuntime };
16|
17|export const SIDEKICK_RUNTIME_ENV_VAR = "PI_APP_SIDEKICK_RUNTIME";
18|
19|export type SidekickRuntimeOverride = "pi" | "muse-cli" | "auto";
20|
21|/** `PI_APP_SIDEKICK_RUNTIME=pi|muse-cli|auto`, defaulting to auto; junk falls back to auto. */
22|export function resolveSidekickRuntimeOverride(
23|  env: NodeJS.ProcessEnv = process.env,
24|): SidekickRuntimeOverride {
25|  const raw = env[SIDEKICK_RUNTIME_ENV_VAR]?.trim().toLowerCase();
26|  if (raw === "pi" || raw === "muse-cli" || raw === "auto") {
27|    return raw;
28|  }
29|  return "auto";
30|}
31|
32|export function isMetaModelSelection(selection: SessionModelSelection | undefined): boolean {
33|  return selection?.provider === "meta";
34|}
35|
36|/**
37| * The stored Meta credential type from pi's own auth file (`meta.type`).
38| * Returns undefined when the file is missing or unparseable. Only the type
39| * field is read; secrets never leave the file.
40| */
41|/** pi's agent dir: its override env var, else ~/.pi/agent (mirrors pi's getAgentDir). */
42|export function defaultAgentDir(): string {
43|  const envDir = process.env.PI_CODING_AGENT_DIR?.trim();
44|  if (envDir) {
45|    return envDir;
46|  }
47|  return join(homedir(), ".pi", "agent");
48|}
49|
50|export function readMetaCredentialType(agentDir: string = defaultAgentDir()): string | undefined {
51|  try {
52|    const parsed: unknown = JSON.parse(readFileSync(join(agentDir, "auth.json"), "utf8"));
53|    if (!parsed || typeof parsed !== "object") {
54|      return undefined;
55|    }
56|    const meta = (parsed as Record<string, unknown>).meta;
57|    if (!meta || typeof meta !== "object") {
58|      return undefined;
59|    }
60|    const type = (meta as Record<string, unknown>).type;
61|    return typeof type === "string" ? type : undefined;
62|  } catch {
63|    return undefined;
64|  }
65|}
66|
67|export interface SidekickRuntimeDecision {
68|  /** The model the child (scout: scout model, else sidekick model) will run. */
69|  readonly model: SessionModelSelection | undefined;
70|  /** True when the Meta credential is an OAuth subscription. */
71|  readonly metaOAuth: boolean;
72|  /** True when a `muse` binary resolves. */
73|  readonly museAvailable: boolean;
74|}
75|
76|/**
77| * Tag a new child with its driver. An explicit override always wins; auto
78| * picks the Muse CLI exactly when the child would run a `meta/*` model on an
79| * OAuth subscription (and a binary exists), otherwise pi.
80| */
81|export function decideChildRuntime(
82|  override: SidekickRuntimeOverride,
83|  decision: SidekickRuntimeDecision,
84|): OrchestrationChildRuntime {
85|  if (override === "pi") {
86|    return "pi";
87|  }
88|  if (override === "muse-cli") {
89|    return "muse-cli";
90|  }
91|  if (!isMetaModelSelection(decision.model) || !decision.metaOAuth || !decision.museAvailable) {
92|    return "pi";
93|  }
94|  return "muse-cli";
95|}
96|
97|/** Sessions without a tag (every pre-v22 record) run on pi. */
98|export function childRuntimeOf(child: {
99|  readonly runtime?: OrchestrationChildRuntime;
100|}): OrchestrationChildRuntime {
101|  return child.runtime === "muse-cli" ? "muse-cli" : "pi";
102|}

